import java.util.Arrays;

public class BankStatementGenerator {

    // ========= Constants (best practice: named constants, not magic numbers) =========
    static final double OPENING_BALANCE     = 50_000.0;
    static final double MIN_BALANCE         = 1_000.0;
    static final double LARGE_TXN_THRESHOLD = 20_000.0;  // Flag transactions over this
    static final String ACCOUNT_NUMBER      = "ACC-9876543210";
    static final String CUSTOMER_NAME       = "Krishvi Achalla";
    static final String ACCOUNT_TYPE        = "Savings";

    public static void main(String[] args) {

        // ========= Transaction Data =========
        // Positive = Credit (money coming IN), Negative = Debit (money going OUT)
        double[] transactions = {
            +15_000,   // Salary credit
            -5_000,    // Electricity bill
            +25_000,   // FD maturity
            -12_000,   // Online shopping
            -3_500,    // Restaurant
            +50_000,   // Client payment
            -45_000,   // Rent payment
            -1_200,    // Mobile recharge
            +8_000,    // Interest credit
            -2_800,    // Grocery
        };

        String[] descriptions = {
            "SALARY-ROBOBANK-FEB", "BESCOM-ELECTRICITY", "FD-MATURITY-12345",
            "AMAZON-PURCHASE", "ZOMATO-FOOD", "CLIENT-PAYMENT-XYZ",
            "RENT-MARCH", "AIRTEL-RECHARGE", "SAVINGS-INT-FEB", "BIGBASKET"
        };

        // ========= Print Statement Header =========
        System.out.println("================================================");
        System.out.println("            RoboBank - Account Statement         ");
        System.out.println("================================================");
        System.out.printf("Customer  : %-30s%n", CUSTOMER_NAME);
        System.out.printf("Account   : %-30s%n", ACCOUNT_NUMBER);
        System.out.printf("Type      : %-30s%n", ACCOUNT_TYPE);
        System.out.printf("Opening   : ₹%,.2f%n", OPENING_BALANCE);
        System.out.println("------------------------------------------------");
        System.out.printf("%-4s %-24s %8s %12s%n", "#", "Description", "Amount", "Balance");
        System.out.println("------------------------------------------------");

        // ========= Process Transactions =========
        double runningBalance = OPENING_BALANCE;
        double totalCredit = 0;
        double totalDebit  = 0;
        int    creditCount = 0;
        int    debitCount  = 0;
        int    largeTxnCount = 0;

        for (int i = 0; i < transactions.length; i++) {
            double txnAmt = transactions[i];
            runningBalance += txnAmt;

            // Categorize
            if (txnAmt > 0) {
                totalCredit += txnAmt;
                creditCount++;
            } else {
                totalDebit += Math.abs(txnAmt);
                debitCount++;
            }

            // Flag large transactions
            boolean isLarge = Math.abs(txnAmt) >= LARGE_TXN_THRESHOLD;
            if (isLarge) largeTxnCount++;
            String flag = isLarge ? " ***" : "";

            // Print transaction row
            String amtStr = (txnAmt > 0 ? "+" : "") + String.format("₹%,.2f", txnAmt);
            System.out.printf("%-4d %-24s %12s  ₹%,.2f%s%n",
                              i + 1, descriptions[i], amtStr, runningBalance, flag);

            // Check minimum balance
            if (runningBalance < MIN_BALANCE) {
                System.out.println("   ⚠ WARNING: Balance below minimum (₹" + MIN_BALANCE + ")");
            }
        }

        // ========= Statement Footer =========
        System.out.println("------------------------------------------------");
        System.out.println("                  STATEMENT SUMMARY");
        System.out.println("------------------------------------------------");
        System.out.printf("Opening Balance  : ₹%,.2f%n", OPENING_BALANCE);
        System.out.printf("Total Credits    : ₹%,.2f (%d transactions)%n", totalCredit, creditCount);
        System.out.printf("Total Debits     : ₹%,.2f (%d transactions)%n", totalDebit, debitCount);
        System.out.printf("Closing Balance  : ₹%,.2f%n", runningBalance);
        System.out.printf("Large Txns (>₹%.0f) : %d%n", LARGE_TXN_THRESHOLD, largeTxnCount);
        System.out.println("------------------------------------------------");

        // Account health using ternary
        String health = (runningBalance >= 10_000) ? "GOOD" :
                        (runningBalance >= MIN_BALANCE) ? "LOW" : "CRITICAL";
        System.out.println("Account Health   : " + health);
        System.out.println("================================================");

        // ========= Sort and show top 3 transactions =========
        double[] absTxns = new double[transactions.length];
        for (int i = 0; i < transactions.length; i++) {
            absTxns[i] = Math.abs(transactions[i]);
        }
        double[] sortedAbs = Arrays.copyOf(absTxns, absTxns.length);
        Arrays.sort(sortedAbs);  // ascending

        System.out.println("\nTop 3 Largest Transactions:");
        for (int i = sortedAbs.length - 1; i >= sortedAbs.length - 3; i--) {
            System.out.printf("  ₹%,.2f%n", sortedAbs[i]);
        }
    }
}
